def highest_Power_of_2(n):
    """Write a python function to find the highest power of 2 that is less than or equal to n.

    Return 0 when no positive power of 2 is less than or equal to ``n``
    (that is, for ``n < 1``).
    """
    if n < 1:
        return 0
    if isinstance(n, int):
        return 1 << (n.bit_length() - 1)
    power = 1
    while power * 2 <= n:
        power *= 2
    return power
